import { fetchLogout } from "../api/JwtApi";
export default function AuthStatus({ user, onLogout }) {
    
    if (!user) return null;

    return (
        <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
            <span>{user.userName}님</span>
            <button onClick={fetchLogout}>로그아웃</button>
        </div>
    );
}
